static void Run()
{
    try { Deep(3); }
    catch (Exception e)
    {
        // frames of Deep and Run.
        // Main, which called Run, is not here.
        Console.WriteLine(e.StackTrace);
    }
}

static void Deep(int n)
{
    if (n == 0) throw new Exception();
    Deep(n - 1);
}

